        while swapped and (i + gap < len(sorted_nums)):
            swapped = False
            if sorted_nums[i] > sorted_nums[i + gap]:
                sorted_nums[i], sorted_nums[i + gap] = sorted_nums[i + gap], sorted_nums[i]
                swapped = True
            i += 1
        if not swapped:
            break

    return sorted_nums
