def sequence(n):
    if n == 1:
        return 1
    elif n == 2:
        return 1
    elif n == 3:
        return 2

    # Generate the Newman-Conway sequence up to the nth term
    seq = [1, 1, 2]

    for i in range(4, n + 1):
        # Count the number of times each number appears consecutively
        count = 1
        for j in range(len(seq) - 1, 0, -1):
            if seq[j] == seq[j - 1]:
                count += 1
            else:
                break
        # Append the count to the sequence
        seq.append(count)

    return seq[n - 1]
```

