def count_binary_seq(n):
    if n == 0:
        return 1
    # The count is given by the central binomial coefficient C(2n, n)
    # which is the (2n) choose n combination
    # This can be computed using a function to avoid overflow with large n
    def comb(a, b):
        if b == 0 or b == a:
            return 1
        b = min(b, a - b)  # Take advantage of symmetry
        res = 1
        for i in range(1, b + 1):
            res = res * (a - b + i) // i
        return res

    return comb(2 * n, n)
